import { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";

import { Plus } from "lucide-react";

import { auth } from "@/app/auth";
import { ProductCard } from "@/components/product-card";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { db } from "@/lib/db";

export const metadata: Metadata = {
  title: "Dashboard",
  description: "Manage your listings and inventory",
};

const marketplaces = [
  { name: "eBay", color: "text-red-500", active: false },
  { name: "Grailed", color: "text-blue-500", active: false },
  { name: "Depop", color: "text-green-500", active: false },
  { name: "OfferUp", color: "text-purple-500", active: false },
];

export default async function DashboardPage() {
  const session = await auth();

  if (!session?.user) {
    redirect("/login");
  }

  // Fetch user's products
  const products = await db.product.findMany({
    where: {
      userId: session.user.id,
    },
    include: {
      images: true,
      listings: {
        include: {
          platform: true,
        },
      },
    },
    orderBy: {
      createdAt: "desc",
    },
  });

  return (
    <div className="flex-1 space-y-6 p-8 pt-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold tracking-tight">Products</h2>
          <p className="text-muted-foreground">Manage your listings across platforms</p>
        </div>
        <Link href="/dashboard/add-product">
          <Button className="bg-blue-500 text-white hover:bg-blue-600">
            <Plus className="mr-2 h-5 w-5" />
            Add Product
          </Button>
        </Link>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Connected Marketplaces</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex flex-wrap gap-4">
            {marketplaces.map((marketplace) => (
              <div
                key={marketplace.name}
                className={`rounded-lg border px-4 py-2 ${
                  marketplace.active ? "border-green-500 bg-green-50" : "border-gray-200"
                }`}
              >
                <span className={marketplace.color}>{marketplace.name}</span>
                <span
                  className={`ml-2 text-sm ${
                    marketplace.active ? "text-green-500" : "text-gray-500"
                  }`}
                >
                  {marketplace.active ? "● Connected" : "○ Disconnected"}
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      <div className="grid grid-cols-1 gap-6 md:grid-cols-2 lg:grid-cols-3">
        {products.length === 0 ? (
          <div className="flex h-48 items-center justify-center rounded-lg border-2 border-dashed border-gray-200">
            <div className="text-center">
              <p className="mb-2 text-gray-500">No products yet</p>
              <Link href="/dashboard/add-product">
                <Button variant="outline" size="sm">
                  <Plus className="mr-2 h-4 w-4" />
                  Add Your First Product
                </Button>
              </Link>
            </div>
          </div>
        ) : (
          products.map((product) => <ProductCard key={product.id} product={product} />)
        )}
      </div>
    </div>
  );
}
